import type { MetadataRoute } from "next";
import { APP_NAME, APP_SHORT_NAME, BACKGROUND_COLOR, SITE_DESCRIPTION, THEME_COLOR } from "@/lib/config";

/** PWA manifest (P2). Icons are self-hosted, generated by scripts/gen-icons.ts. */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: APP_NAME,
    short_name: APP_SHORT_NAME,
    description: SITE_DESCRIPTION,
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: BACKGROUND_COLOR,
    theme_color: THEME_COLOR,
    lang: "en-US",
    categories: ["shopping", "lifestyle"],
    icons: [
      { src: "/icons/hues-icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/hues-icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/hues-icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
      { src: "/icons/hues-icon.svg", sizes: "any", type: "image/svg+xml", purpose: "any" },
    ],
    shortcuts: [
      { name: "Search seeds", url: "/search", icons: [{ src: "/icons/hues-icon-192.png", sizes: "192x192" }] },
      { name: "Sellers", url: "/seller", icons: [{ src: "/icons/hues-icon-192.png", sizes: "192x192" }] },
    ],
  };
}
